158	    @Transactional
159	    @Override
160	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
161	        Owner owner = this.clinicService.findOwnerById(ownerId);
162	        if (owner == null) {
163	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
164	        }
165	        owner.setDeleted(true);
166	        this.clinicService.saveOwner(owner);
167	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
168	    }
