16	package org.springframework.samples.petclinic.model;
17	
18	import java.util.List;
19	
20	/**
21	 * Pure, stateless helpers over a telephone number in E.164 form, together with the
22	 * fixed table of recognised country dialling codes that governs them.
23	 *
24	 * <p>Like {@link OwnerDerivations}, these operate on a bare value (here a telephone
25	 * string) rather than on an {@link Owner}, so they stay stateless and side-effect
26	 * free. Keeping the E.164 rules and their single country-code table together in one
27	 * place lets the REST boundary normalise an incoming number to canonical form while
28	 * the owner derivations read the same stored number back, without either side having
29	 * to restate what a country code is or how long its national number runs.
30	 */
31	public final class Telephones {
32	
33	    /**
34	     * A recognised country dialling code and the exact national-number length it
35	     * pins. The {@code code} is the leading run of digits that identifies the country
36	     * ({@code "61"} for Australia, {@code "1"} for the NANP), so the country code's
37	     * own length is simply {@code code.length()}.
38	     */
39	    private record CountryCode(String code, int nationalNumberLength) {
40	    }
41	
42	    /**
43	     * The fixed table of recognised country dialling codes, listed longest code first
44	     * so a lookup matches the most specific code a number begins with. A country code
45	     * absent from this table carries no pinned national-number length.
46	     */
47	    private static final List<CountryCode> COUNTRY_CODES = List.of(
48	        new CountryCode("61", 9), new CountryCode("1", 10));
49	
50	    private Telephones() {
51	    }
52	
53	    /**
54	     * Normalise a telephone number to E.164 form: keep a leading '+' and country
55	     * code when present, otherwise assume country code '+61' and drop a single
56	     * leading '0' from the national digits. Spaces, dashes and brackets are
57	     * stripped. The result must contain 8 to 15 digits after the '+'.
58	     *
59	     * <p>In addition, the national-number length is validated against the country
60	     * code: a {@code +61} (Australia) number must have exactly 9 national digits
61	     * and a {@code +1} (NANP) number must have exactly 10 national digits. A number
62	     * whose national-number length is wrong for its country code is rejected.
63	     *
64	     * @return the E.164 string (e.g. "+61412345678"), or {@code null} if the
65	     *         input cannot form a valid E.164 number.
66	     */
67	    public static String toE164(String raw) {
68	        if (raw == null) {
69	            return null;
70	        }
71	        String cleaned = raw.replaceAll("[\\s()-]", "");
72	        String digits;
73	        if (cleaned.startsWith("+")) {
74	            digits = cleaned.substring(1);
75	        } else {
76	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
77	            digits = "61" + national;
78	        }
79	        if (!digits.matches("\\d{8,15}")) {
80	            return null;
81	        }
82	        if (!nationalNumberLengthValid(digits)) {
83	            return null;
84	        }
85	        return "+" + digits;
86	    }
87	
88	    /**
89	     * Format an E.164 telephone number for humans: a leading '+' and country
90	     * code, a space, then the national digits (the digits after the country
91	     * code) grouped in threes from the left, e.g. {@code "+61412345678"} becomes
92	     * {@code "+61 412 345 678"}. When the number begins with no recognised
93	     * country code, all digits after the '+' are grouped in threes with no
94	     * separate country-code group.
95	     *
96	     * @param e164 the stored telephone number in E.164 form (e.g. "+61412345678")
97	     * @return the human-formatted number, or {@code null} if {@code e164} is
98	     *         {@code null} or not a '+' followed by digits.
99	     */
100	    public static String toDisplay(String e164) {
101	        if (e164 == null || !e164.startsWith("+")) {
102	            return null;
103	        }
104	        String digits = e164.substring(1);
105	        if (!digits.matches("\\d+")) {
106	            return null;
107	        }
108	        CountryCode country = countryCodeFor(digits);
109	        if (country == null) {
110	            return "+" + groupInThrees(digits);
111	        }
112	        String code = country.code();
113	        String national = digits.substring(code.length());
114	        return "+" + code + " " + groupInThrees(national);
115	    }
116	
117	    /**
118	     * Group a run of digits into space-separated chunks of three, from the left,
119	     * so a final short chunk keeps the remaining one or two digits.
120	     */
121	    private static String groupInThrees(String digits) {
122	        StringBuilder grouped = new StringBuilder();
123	        for (int i = 0; i < digits.length(); i++) {
124	            if (i > 0 && i % 3 == 0) {
125	                grouped.append(' ');
126	            }
127	            grouped.append(digits.charAt(i));
128	        }
129	        return grouped.toString();
130	    }
131	
132	    /**
133	     * Validate the length of the national number (the digits after the country
134	     * code) against the country code carried by the given E.164 digit string: a
135	     * {@code 61} (Australia) number requires exactly 9 national digits and a
136	     * {@code 1} (NANP) number requires exactly 10 national digits. Country codes
137	     * without a pinned length are accepted (only the generic 8-15 digit rule
138	     * applies to them).
139	     *
140	     * @param digits the E.164 digits without the leading '+'
141	     * @return {@code true} if the national-number length is correct for the country
142	     */
143	    private static boolean nationalNumberLengthValid(String digits) {
144	        CountryCode country = countryCodeFor(digits);
145	        if (country == null) {
146	            return true;
147	        }
148	        return digits.length() - country.code().length() == country.nationalNumberLength();
149	    }
150	
151	    /**
152	     * The recognised country dialling code that the given E.164 digit string (no
153	     * leading '+') begins with, or {@code null} when it begins with no code in the
154	     * fixed table. The longest matching code wins.
155	     */
156	    private static CountryCode countryCodeFor(String digits) {
157	        for (CountryCode country : COUNTRY_CODES) {
158	            if (digits.startsWith(country.code())) {
159	                return country;
160	            }
161	        }
162	        return null;
163	    }
164	}
